function [m] = mjd_of(u)
%MJD_OF  The UTC modified Julian date of a [Y Mo D H Mi S].
%   u: real[1][6] (passed a plain number)
%   returns m: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = 0;
    [djm0, djm] = asils.models.iau2006.cal2jd_sofa(u(1), u(2), u(3));
    m = (djm + ((((u(4) * 3600) + (u(5) * 60)) + u(6)) / 86400));
end
